{"path":"pricing.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Fees & Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbf8f5;--card:#ffffff;--muted:#6b6b6b;--accent:#6b8e6a;--accent-2:#8aa6a3;--glass:rgba(255,255,255,0.7);--shadow:0 6px 18px rgba(15,15,15,0.06)}
    *{box-sizing:border-box}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;line-height:1.45;color:#222;background:linear-gradient(180deg,var(--bg),#f7f5f2)}
    header{position:sticky;top:0;backdrop-filter:saturate(1.1) blur(6px);background:rgba(255,255,255,0.7);border-bottom:1px solid rgba(0,0,0,0.04);z-index:40}
    .nav{max-width:1100px;margin:0 auto;display:flex;align-items:center;gap:18px;padding:14px}
    .brand{font-weight:700;color:var(--accent);letter-spacing:0.3px}
    nav a{color:#333;text-decoration:none;padding:8px 10px;border-radius:8px;font-size:15px}
    nav a.cta{background:var(--accent);color:#fff}
    .container{max-width:1100px;margin:34px auto;padding:0 20px}
    .hero{display:grid;grid-template-columns:1fr 340px;gap:26px;align-items:start;margin-bottom:28px}
    .hero .lead{background:linear-gradient(180deg,rgba(255,255,255,0.9),var(--glass));padding:28px;border-radius:14px;box-shadow:var(--shadow)}
    h1{margin:0 0 8px 0;font-size:28px}
    p.lead{margin:0;color:var(--muted)}

    .meta{font-size:13px;color:var(--muted);margin-top:12px}
    .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:20px}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:var(--shadow)}
    .card h3{margin:0 0 6px 0}
    .price{font-weight:700;color:var(--accent-2);font-size:20px}
    .features{color:var(--muted);font-size:14px;margin-top:8px}
    .addons{margin-top:12px;border-top:1px dashed rgba(0,0,0,0.06);padding-top:12px}
    .addon{display:flex;justify-content:space-between;padding:8px 0;font-size:14px}
    .btn{display:inline-block;padding:9px 12px;border-radius:10px;background:var(--accent);color:#fff;text-decoration:none}

    footer{max-width:1100px;margin:40px auto 80px auto;padding:0 20px;color:var(--muted)}

    /* subtle pattern svg background */
    .bg-pattern{position:fixed;right:-80px;top:-60px;width:420px;height:420px;opacity:0.08;pointer-events:none}

    /* reveal */
    .reveal{opacity:0;transform:translateY(14px);transition:opacity 520ms cubic-bezier(.2,.9,.2,1),transform 520ms cubic-bezier(.2,.9,.2,1)}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}

    @media (max-width:880px){.hero{grid-template-columns:1fr;}.grid{grid-template-columns:1fr 1fr}.container{padding:0 16px}}
    @media (max-width:560px){.grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <svg class='bg-pattern' viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg' aria-hidden='true'>
    <defs>
      <linearGradient id='g1' x1='0' x2='1'>
        <stop offset='0' stop-color='#b7d6c8'/>
        <stop offset='1' stop-color='#e4efe9'/>
      </linearGradient>
    </defs>
    <rect x='0' y='0' width='200' height='200' fill='url(#g1)' rx='28'/>
    <g fill='rgba(255,255,255,0.35)'>
      <circle cx='40' cy='40' r='18'/>
      <circle cx='160' cy='140' r='26'/>
      <circle cx='120' cy='40' r='10'/>
    </g>
    <path d='M6 180 C40 120, 80 140, 140 100' stroke='rgba(255,255,255,0.2)' stroke-width='3' fill='none' stroke-linecap='round'/>
  </svg>

  <header>
    <div class='nav'>
      <div class='brand'>{{BUSINESS_NAME}}</div>
      <nav style='margin-left:18px;flex:1'>
        <a href='index.html'>Home</a>
        <a href='services.html'>Offerings</a>
        <a href='conditions.html'>Ailments</a>
        <a href='approach.html'>Method</a>
        <a href='pricing.html' class='cta'>Fees</a>
        <a href='about.html'>Studio</a>
        <a href='book.html'>Schedule</a>
        <a href='contact.html'>Connect</a>
      </nav>
      <a href='{{PRIMARY_CTA_URL}}' class='btn'>{{PRIMARY_CTA_LABEL}}</a>
    </div>
  </header>

  <main class='container'>
    <section class='hero'>
      <div class='lead reveal'>
        <h1>Care paths priced for flexibility and gentle progress</h1>
        <p class='lead'>Choose discrete sessions or a guided series that gives space for reflection, small shifts, and sustainable rhythms. Add supportive home tools if you wish.</p>
        <div class='meta'>Phone: <a href='tel:{{PHONE}}'>{{PHONE}}</a> • Email: <a href='mailto:{{EMAIL}}'>{{EMAIL}}</a></div>
      </div>

      <aside class='card reveal' aria-labelledby='pricing-side'>
        <h3 id='pricing-side'>Quick booking</h3>
        <p style='color:var(--muted);margin:8px 0 16px 0'>Reserve a session or begin with the Session Planner on the Schedule page to receive a tailored suggestion.</p>
        <a href='book.html' class='btn' style='display:inline-block'>Reserve a time</a>
      </aside>
    </section>

    <section class='reveal'>
      <div style='display:flex;justify-content:space-between;align-items:end'>
        <div>
          <h2 style='margin:0 0 8px 0'>Offerings & add-ons</h2>
          <p style='margin:0;color:var(--muted)'>Packages are framed to encourage doable habits and practical at-home companions.</p>
        </div>
        <div style='font-size:13px;color:var(--muted)'>All sessions are educational and supportive, not a substitute for medical care.</div>
      </div>

      <div class='grid' style='margin-top:16px'>
        <div class='card'>
          <h3>Single Visit — 'Clarity' session</h3>
          <div class='price'>$120 / 60 min</div>
          <div class='features'>A focused intake and prioritized home plan. Good when you want clear next steps.</div>
          <div style='margin-top:12px'><a href='book.html' class='btn'>Book one</a></div>
        </div>

        <div class='card'>
          <h3>Short Series — 'Rhythm' pack</h3>
          <div class='price'>$330 / 3 sessions</div>
          <div class='features'>Three visits spaced over weeks; review, refine, and practice small routines between appointments.</div>
          <div style='margin-top:12px'><a href='book.html' class='btn'>Reserve the series</a></div>
        </div>

        <div class='card'>
          <h3>Guided Path — 'Root & Flow' program</h3>
          <div class='price'>$600 / 6 sessions</div>
          <div class='features'>An extended program for deeper habit-setting, seasonal planning, and stepwise support.</div>
          <div style='margin-top:12px'><a href='book.html' class='btn'>Begin a path</a></div>
        </div>
      </div>

      <div style='display:flex;gap:18px;margin-top:18px;flex-wrap:wrap'>
        <div class='card' style='flex:1;min-width:300px'>
          <h3>At-home companions (retail)</h3>
          <div class='addons'>
            <div class='addon'><span>Therapeutic roll-on blend</span><strong>$28</strong></div>
            <div class='addon'><span>Soothing inhaler kit</span><strong>$22</strong></div>
            <div class='addon'><span>Seasonal support pack</span><strong>$44</strong></div>
          </div>
          <p style='margin:10px 0 0 0;font-size:13px;color:var(--muted)'>Add-ons are curated to reinforce session work. Guidance provided on safe, everyday use.</p>
        </div>

        <div class='card' style='min-width:260px'>
          <h3>Custom add-ons</h3>
          <p style='color:var(--muted)'>If you have specific requests (groups, workplace sessions, longer format), we can tailor a quote.</p>
          <div style='margin-top:10px'><a href='contact.html' class='btn'>Request a quote</a></div>
        </div>
      </div>
    </section>

    <section class='reveal' style='margin-top:22px'>
      <h2 style='margin:0 0 10px 0'>How billing works</h2>
      <p style='color:var(--muted)'>Sessions are billed at the time of booking for single visits. Series are billed per-package; add-ons are purchased separately. We accept payment by card. Refunds and rescheduling follow the policies explained at booking.</p>
    </section>

    <section class='reveal' style='margin-top:18px'>
      <h2 style='margin:0 0 10px 0'>A note on care</h2>
      <p style='color:var(--muted)'>Our work is educational and supportive. We do not promise cures. If you have urgent medical needs, please contact appropriate healthcare resources immediately.</p>
    </section>

  </main>

  <footer>
    <div style='max-width:1100px;margin:0 auto;padding:0 20px;display:flex;justify-content:space-between;align-items:center'>
      <div style='color:var(--muted)'>© <span id='yr'></span> {{BUSINESS_NAME}} — {{CITY}}, {{STATE}}</div>
      <div style='color:var(--muted)'>Questions? <a href='contact.html'>Get in touch</a></div>
    </div>
  </footer>

  <script>
    document.getElementById('yr').textContent = new Date().getFullYear();
    // reveal on scroll with reduced-motion support
    (function(){
      var prefersReduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var reveals = document.querySelectorAll('.reveal');
      if(prefersReduced){reveals.forEach(function(r){r.classList.add('visible')}); return}
      if('IntersectionObserver' in window){
        var io = new IntersectionObserver(function(entries){
          entries.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('visible'); io.unobserve(e.target) } })
        },{threshold:0.12});
        reveals.forEach(function(r){io.observe(r)});
      } else { reveals.forEach(function(r){r.classList.add('visible')}) }
    })();
  </script>
</body>
</html>"} 
{"path":"about.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Studio & Story — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff;--muted:#666;--accent:#7a9d74;--card:#fff;--shadow:0 8px 24px rgba(12,12,12,0.06)}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;color:#1f1f1f;background:linear-gradient(180deg,#fbfbfa,#f6f7f6)}
    header{position:sticky;top:0;background:rgba(255,255,255,0.9);backdrop-filter:blur(6px);border-bottom:1px solid rgba(0,0,0,0.04);z-index:40}
    .nav{max-width:1100px;margin:0 auto;display:flex;align-items:center;gap:18px;padding:12px}
    .brand{font-weight:700;color:var(--accent)}
    nav{margin-left:18px;flex:1}
    nav a{padding:8px 10px;border-radius:8px;text-decoration:none;color:#333}
    nav a.active{background:var(--accent);color:#fff}
    .container{max-width:1100px;margin:30px auto;padding:0 20px}

    .story{display:grid;grid-template-columns:1fr 340px;gap:22px;align-items:start}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:var(--shadow)}
    h1{margin:0;font-size:26px}
    .byline{color:var(--muted);margin-top:8px}

    .mosaic{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:18px}
    .mosaic .item{background:#f4f6f4;padding:14px;border-radius:10px}

    .quote{font-style:italic;color:#555;padding:14px;border-left:3px solid var(--accent);background:linear-gradient(90deg,rgba(122,157,116,0.04),transparent);border-radius:8px}

    .reveal{opacity:0;transform:translateY(12px);transition:opacity 520ms ease,transform 520ms ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}

    @media (max-width:880px){.story{grid-template-columns:1fr}.mosaic{grid-template-columns:1fr 1fr}}
    @media (max-width:560px){.mosaic{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class='nav'>
      <div class='brand'>{{BUSINESS_NAME}}</div>
      <nav>
        <a href='index.html'>Home</a>
        <a href='services.html'>Offerings</a>
        <a href='conditions.html'>Ailments</a>
        <a href='approach.html'>Method</a>
        <a href='pricing.html'>Fees</a>
        <a href='about.html' class='active'>Studio</a>
        <a href='book.html'>Schedule</a>
        <a href='contact.html'>Connect</a>
      </nav>
      <a href='{{PRIMARY_CTA_URL}}' class='btn' style='background:var(--accent);color:#fff;padding:8px 12px;border-radius:10px;text-decoration:none'>{{PRIMARY_CTA_LABEL}}</a>
    </div>
  </header>

  <main class='container'>
    <section class='story'>
      <div class='card reveal'>
        <h1>Where practical wisdom meets everyday living</h1>
        <div class='byline'>A place for small, reliable changes and clear, usable guidance.</div>
        <p style='margin-top:12px;color:var(--muted)'>We favor modest routines you can return to across seasons — ideas that slot into your day rather than upend it. Each visit is a conversation that yields clear, usable steps and optional at-home supports you can purchase if helpful.</p>

        <div style='margin-top:14px'>
          <h3 style='margin:0 0 8px 0'>Background</h3>
          <p style='margin:0;color:var(--muted)'>Practitioner training blends clinical foundations with plant-centered practices and behavior-focused coaching. The aim is to scaffold lived routines that feel achievable.</p>
        </div>

        <div style='margin-top:14px'>
          <h3 style='margin:0 0 8px 0'>Philosophy</h3>
          <p style='margin:0;color:var(--muted)'>We work with the whole of your day — sleep, meals, movement, and simple sensory anchors — to support steadier patterns rather than dramatic interventions.</p>
        </div>
      </div>

      <aside class='card reveal' aria-labelledby='studio-side'>
        <h3 id='studio-side'>Studio details</h3>
        <p style='color:var(--muted);margin:6px 0'>Located in {{CITY}}, {{STATE}}. Remote sessions are available when appropriate. Accessibility notes and parking instructions are provided at booking.</p>
        <div style='margin-top:12px'><a href='contact.html' class='btn' style='background:var(--accent);color:#fff;text-decoration:none;padding:8px 10px;border-radius:8px'>Ask a question</a></div>
      </aside>
    </section>

    <section style='margin-top:18px'>
      <div class='mosaic'>
        <div class='item reveal'>
          <h4 style='margin:0 0 6px 0'>Core skill: attention</h4>
          <p style='margin:0;color:var(--muted)'>We practice noticing the triggers and patterns that shape a day — then choose one small pivot to try before the next visit.</p>
        </div>
        <div class='item reveal'>
          <h4 style='margin:0 0 6px 0'>Tools that support</h4>
          <p style='margin:0;color:var(--muted)'>Light-touch companions such as roll-ons or inhalers are presented as optional aids, with clear guidance on safe use.</p>
        </div>
        <div class='item reveal'>
          <h4 style='margin:0 0 6px 0'>Tailored pacing</h4>
          <p style='margin:0;color:var(--muted)'>Every plan is paced to fit your life — frequency and intensity set to keep momentum without overwhelm.</p>
        </div>
      </div>

      <div style='margin-top:18px' class='reveal'>
        <div class='quote'>"Care that listens first makes room for change to feel meaningful."</div>
      </div>
    </section>

    <section style='margin-top:20px' class='reveal'>
      <h3 style='margin:0 0 8px 0'>A gentle policy note</h3>
      <p style='color:var(--muted);margin:0'>Services are educational and supportive. They are not a replacement for medical treatment. If you have urgent health concerns, please follow advice from your healthcare provider or emergency services.</p>
    </section>

  </main>

  <script>
    // simple reveal observer used across pages
    (function(){
      var prefersReduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var reveals = document.querySelectorAll('.reveal');
      if(prefersReduced){reveals.forEach(function(r){r.classList.add('visible')}); return}
      if('IntersectionObserver' in window){
        var io = new IntersectionObserver(function(entries){entries.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('visible'); io.unobserve(e.target) } })},{threshold:0.12});
        reveals.forEach(function(r){io.observe(r)});
      } else {reveals.forEach(function(r){r.classList.add('visible')})}
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang='en'>
<head>
  <meta charset='utf-8'>
  <meta name='viewport' content='width=device-width,initial-scale=1'>
  <title>Schedule & Session Planner — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f8fbf8;--muted:#5f6366;--accent:#6b9b79;--card:#fff;--shadow:0 10px 30px rgba(12,12,12,0.06)}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;background:var(--bg);color:#222}
    header{position:sticky;top:0;background:rgba(255,255,255,0.9);backdrop-filter:blur(6px);border-bottom:1px solid rgba(0,0,0,0.04)}
    .nav{max-width:1100px;margin:0 auto;display:flex;align-items:center;gap:18px;padding:12px}
    .brand{font-weight:700;color:var(--accent)}
    nav{margin-left:18px;flex:1}
    nav a{padding:8px 10px;border-radius:8px;text-decoration:none;color:#333}
    .container{max-width:1100px;margin:28px auto;padding:0 20px}

    .grid{display:grid;grid-template-columns:1fr 420px;gap:22px}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:var(--shadow)}
    h1{margin:0 0 6px 0}
    .muted{color:var(--muted)}

    /* session planner */
    .planner label{display:block;font-size:13px;margin-top:10px;color:#333}
    .planner input[type='text'],.planner select,.planner textarea{width:100%;padding:10px;border-radius:8px;border:1px solid #e6e8e6;margin-top:6px;font-size:14px}
    .options{display:flex;gap:10px;flex-wrap:wrap;margin-top:10px}
    .chip{background:#f1f6f1;padding:8px 10px;border-radius:999px;font-size:13px;color:#2f4b39;border:1px solid rgba(47,75,57,0.06);cursor:pointer}
    .chip.selected{background:var(--accent);color:#fff}
    .actions{display:flex;gap:10px;margin-top:12px}
    .btn{padding:9px 12px;border-radius:10px;background:var(--accent);color:#fff;text-decoration:none;border:none}
    .btn.secondary{background:#fff;color:var(--accent);border:1px solid rgba(107,155,121,0.18)}
    .summary{margin-top:12px}
    .summary textarea{height:160px;font-family:inherit}

    .reveal{opacity:0;transform:translateY(12px);transition:opacity 520ms cubic-bezier(.2,.9,.2,1),transform 520ms cubic-bezier(.2,.9,.2,1)}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion:reduce){.reveal{transition:none;opacity:1;transform:none}}

    @media (max-width:960px){.grid{grid-template-columns:1fr}.planner .aside{order:2}}
  </style>
</head>
<body>
  <header>
    <div class='nav'>
      <div class='brand'>{{BUSINESS_NAME}}</div>
      <nav>
        <a href='index.html'>Home</a>
        <a href='services.html'>Offerings</a>
        <a href='conditions.html'>Ailments</a>
        <a href='approach.html'>Method</a>
        <a href='pricing.html'>Fees</a>
        <a href='about.html'>Studio</a>
        <a href='book.html' class='active'>Schedule</a>
        <a href='contact.html'>Connect</a>
      </nav>
      <a href='{{PRIMARY_CTA_URL}}' class='btn' style='text-decoration:none'>{{PRIMARY_CTA_LABEL}}</a>
    </div>
  </header>

  <main class='container'>
    <section class='grid'>
      <div class='card reveal'>
        <h1>Plan a session</h1>
        <p class='muted'>Use the Session Planner below to shape a concise plan you can bring to your visit or use at home.</p>

        <div class='planner' style='margin-top:12px'>
          <label for='name'>Your name</label>
          <input id='name' type='text' placeholder='First & last name'>

          <label for='goal'>What would you like to address?</label>
          <input id='goal' type='text' placeholder='A brief focus (sleep, mood, stress, routines)'>

          <label>Areas to prioritize</label>
          <div class='options' id='areas'>
            <button type='button' class='chip' data-value='Sleep'>Sleep</button>
            <button type='button' class='chip' data-value='Stress management'>Stress management</button>
            <button type='button' class='chip' data-value='Energy & focus'>Energy & focus</button>
            <button type='button' class='chip' data-value='Daily rhythm'>Daily rhythm</button>
            <button type='button' class='chip' data-value='Sensory anchors'>Sensory anchors</button>
            <button type='button' class='chip' data-value='Breath practice'>Breath practice</button>
          </div>

          <label for='length'>Preferred session length</label>
          <select id='length'>
            <option value='30'>30 minutes</option>
            <option value='60' selected>60 minutes</option>
            <option value='90'>90 minutes</option>
          </select>

          <label for='frequency'>Frequency you prefer</label>
          <select id='frequency'>
            <option value='one-off'>One visit</option>
            <option value='weekly'>Weekly</option>
            <option value='biweekly'>Every two weeks</option>
            <option value='monthly'>Monthly check-ins</option>
          </select>

          <label for='notes'>Anything else to mention</label>
          <textarea id='notes' placeholder='Allergies, current care, what has helped before...'></textarea>

          <div class='actions'>
            <button id='build' class='btn' type='button'>Create plan</button>
            <button id='clear' class='btn secondary' type='button'>Reset</button>
            <a href='pricing.html' class='btn secondary' style='text-decoration:none'>See fees</a>
          </div>

          <div class='summary' id='resultBox' style='display:none'>
            <label style='display:block;font-size:13px;margin-bottom:6px'>Plan summary (plaintext)</label>
            <textarea id='summary' readonly></textarea>
            <div style='display:flex;gap:10px;margin-top:8px'>
              <button id='copy' class='btn' type='button'>Copy to clipboard</button>
              <button id='download' class='btn secondary' type='button'>Download .txt</button>
              <a href='book.html' class='btn' style='text-decoration:none;display:inline-flex;align-items:center'>Proceed to booking</a>
            </div>
          </div>
        </div>
      </div>

      <aside class='card reveal aside'>
        <h3 style='margin:0 0 8px 0'>How to use this</h3>
        <p class='muted' style='margin:0 0 10px 0'>The planner creates a concise, portable summary you can copy into a booking note or bring to your session. It is meant to clarify priorities and preferences.</p>

        <h4 style='margin-top:12px'>Privacy & safety</h4>
        <p class='muted' style='margin:0'>Entries remain local in your browser. We do not transmit planner content until you share it via copy or download.</p>

        <h4 style='margin-top:12px'>Need help now?</h4>
        <p class='muted' style='margin:0'>If you are in immediate crisis or have urgent medical concerns, please contact appropriate emergency services or your healthcare provider.</p>
      </aside>
    </section>
  </main>

  <script>
    // reveal setup
    (function(){
      var prefersReduced = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      var reveals = document.querySelectorAll('.reveal');
      if(prefersReduced){reveals.forEach(function(r){r.classList.add('visible')}); return}
      if('IntersectionObserver' in window){
        var io = new IntersectionObserver(function(entries){entries.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add('visible'); io.unobserve(e.target) } })},{threshold:0.12});
        reveals.forEach(function(r){io.observe(r)});
      } else {reveals.forEach(function(r){r.classList.add('visible')})}
    })();

    // Session Planner logic
    (function(){
      var chips = document.querySelectorAll('.chip');
      var selected = new Set();
      chips.forEach(function(c){
        c.addEventListener('click',function(){
          var v = c.getAttribute('data-value');
          if(c.classList.contains('selected')){ c.classList.remove('selected'); selected.delete(v) }
          else{ c.classList.add('selected'); selected.add(v) }
        });
      });

      function buildText(){
        var name = (document.getElementById('name').value || '').trim();
        var goal = (document.getElementById('goal').value || '').trim();
        var length = document.getElementById('length').value;
        var freq = document.getElementById('frequency').value;
        var notes = (document.getElementById('notes').value || '').trim();
        var areas = Array.from(selected).join(', ');

        var lines = [];
        lines.push('Session Planner — {{BUSINESS_NAME}}');
        if(name) lines.push('Name: ' + name);
        if(goal) lines.push('Focus: ' + goal);
        if(areas) lines.push('Priority areas: ' + areas);
        lines.push('Preferred length: ' + length + ' minutes');
        lines.push('Preferred cadence: ' + freq.replace('-',' '));
        if(notes) lines.push('\nNotes: ' + notes);
        lines.push('\nContact: ' + '{{EMAIL}}' + ' | ' + '{{PHONE}}');
        return lines.join('\n');
      }

      var buildBtn = document.getElementById('build');
      var clearBtn = document.getElementById('clear');
      var resultBox = document.getElementById('resultBox');
      var summary = document.getElementById('summary');
      var copyBtn = document.getElementById('copy');
      var downloadBtn = document.getElementById('download');

      buildBtn.addEventListener('click',function(){
        var text = buildText();
        summary.value = text;
        resultBox.style.display = 'block';
        summary.focus();
        summary.select();
      });

      clearBtn.addEventListener('click',function(){
        document.getElementById('name').value='';
        document.getElementById('goal').value='';
        document.getElementById('length').value='60';
        document.getElementById('frequency').value='one-off';
        document.getElementById('notes').value='';
        selected.clear();
        chips.forEach(function(c){c.classList.remove('selected')});
        resultBox.style.display='none';
        summary.value='';
      });

      copyBtn.addEventListener('click',function(){
        var text = summary.value; if(!text) return;
        if(navigator.clipboard && navigator.clipboard.writeText){
          navigator.clipboard.writeText(text).then(function(){ copyBtn.textContent='Copied' ; setTimeout(function(){copyBtn.textContent='Copy to clipboard'},1600) });
        } else {
          // fallback
          summary.select(); try{ document.execCommand('copy'); copyBtn.textContent='Copied'; setTimeout(function(){copyBtn.textContent='Copy to clipboard'},1600) }catch(e){ alert('Copy not available') }
        }
      });

      downloadBtn.addEventListener('click',function(){
        var text = summary.value || buildText();
        var blob = new Blob([text],{type:'text/plain'});
        var url = URL.createObjectURL(blob);
        var a = document.createElement('a'); a.href = url; a.download = 'session-plan.txt'; document.body.appendChild(a); a.click(); setTimeout(function(){URL.revokeObjectURL(url); a.remove()},250);
      });
    })();
  </script>
</body>
